  // hence the cast.
  return createTransportTreeFromLoaderTreeImpl(
    loaderTree,
    true,
    hintTree,
    prefetchInliningEnabled,
    missingPrefetchHintPolicy,
    partialPrefetching,
    getDynamicParamFromSegment,
    false,
    notFoundParams
  ) as Promise<FullTransportNode>
}

